EXPORT ZZT_TRIMAP() BEGIN
Xmin:=0; Xmax:=318; Ymin:=-218; Ymax:=0;
DIMGROB_P(G1,7,7,#FFFFFFh); DIMGROB_P(G2,7,7,#FFFFFFh);
LOCAL ok1:=1,ok2:=1,x,y,a:={},b:={};
IFERR TRIANGLE(G1,-1,0,4,0,-1,-5,#FF0000h); THEN ok1:=0; END;
IFERR TRIANGLE_P(G2,0,0,5,0,0,5,#FF0000h); THEN ok2:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 6 DO
  a:=CONCAT(a,{B→R(GETPIX_P(G1,x,y))}); b:=CONCAT(b,{B→R(GETPIX_P(G2,x,y))});
END;END;
RETURN {ok1,ok2,a,b};
END;

