IFERR rv:=TRIANGLE_P(G1,0,0,5,0,0,5,#FF0000h); THEN ok:=0; END;
image:={ok,rv};
FOR y FROM 0 TO 6 DO
  mask:=0; bit:=1;
  FOR x FROM 0 TO 6 DO
    IF B→R(GETPIX_P(G1,x,y))≠16777215 THEN mask:=mask+bit; END;
    bit:=2*bit;
  END;
  image:=CONCAT(image,{mask});
END;
out:=CONCAT(out,{image});
